import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

function startOfDay(date: Date): Date {
  const copy = new Date(date);
  copy.setHours(0, 0, 0, 0);
  return copy;
}

function addDays(date: Date, amount: number): Date {
  const copy = new Date(date);
  copy.setDate(copy.getDate() + amount);
  return copy;
}

function isSameDay(a: Date | null, b: Date): boolean {
  if (!a) return false;
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

interface ReportDatePickerProps {
  onChange?: (date: Date | null) => void;
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [value, setValue] = useState<Date | null>(null);

  const today = startOfDay(new Date());
  const yesterday = addDays(today, -1);
  const weekAgo = addDays(today, -7);

  const quickOptions = [
    { label: 'Сегодня', date: today },
    { label: 'Вчера', date: yesterday },
    { label: 'Неделя назад', date: weekAgo },
  ];

  const handleChange = (date: Date | null) => {
    setValue(date);
    onChange?.(date);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-sm)',
      }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор даты"
        style={{ display: 'flex', gap: 'var(--jx-r-xs)', flexWrap: 'wrap' }}
      >
        {quickOptions.map((option) => (
          <JxChip
            key={option.label}
            active={isSameDay(value, option.date)}
            onClick={() => handleChange(option.date)}
          >
            {option.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar value={value} onValueChange={handleChange} />
    </div>
  );
}

